import { getUserContext } from '@/lib/supabase/user-context'
import { createClient } from '@/lib/supabase/server'
import { PortalHeader, PortalTable, EmptyState, formatTime } from '@/components/portal/portal-shell'

export default async function PortalTimetablePage() { const context = await getUserContext(); const supabase = await createClient(); const { data: profile } = await supabase.from('profiles').select('student_id').eq('id', context!.userId).maybeSingle(); const { data: links } = await supabase.from('parent_student_links').select('student_id').eq('parent_profile_id', context!.userId); const ids = [...new Set([...(links ?? []).map((x) => x.student_id), ...(profile?.student_id ? [profile.student_id] : [])])]; const { data: memberships } = ids.length ? await supabase.from('batch_students').select('batch_id').in('student_id', ids) : { data: [] as { batch_id: string }[] }; const batchIds = [...new Set((memberships ?? []).map((x) => x.batch_id))]; const { data } = batchIds.length ? await supabase.from('schedules').select('day_of_week,start_time,end_time,subject,room,teachers(full_name)').in('batch_id', batchIds).order('day_of_week').order('start_time') : { data: [] as any[] }; return <><PortalHeader title="Timetable" description="Your assigned batch schedule." />{data?.length ? <PortalTable headers={['Day', 'Time', 'Subject', 'Teacher', 'Room']} rows={data.map((row: any) => [row.day_of_week, `${formatTime(row.start_time)} – ${formatTime(row.end_time)}`, row.subject || '—', row.teachers?.full_name || '—', row.room || '—'])} /> : <EmptyState text="No timetable entries are available for your assigned batch." />}</> }
